import { equal, match, notEqual, ok, throws } from 'node:assert'
import { after, before, describe, test } from 'node:test'

import * as browser from '../index.browser.js'
import * as node from '../index.js'

for (let type of ['node', 'browser']) {
  let { customAlphabet, customRandom, nanoid, random, urlAlphabet } =
    type === 'node' ? node : browser

  describe(type, () => {
    if (type === 'browser') {
      before(() => {
        Object.defineProperty(global, 'crypto', {
          configurable: true,
          value: {

test('does not hang on negative size (customAlphabet)', () => {
  equal(customAlphabet('abcdef')(-1), '')
  equal(customAlphabet('abcdef', -5)(), '')
})

describe('customAlphabet', () => {
  test(`has options`, () => {
    let nanoidA = customAlphabet('a', 5)
    equal(nanoidA(), 'aaaaa')
  })

  test(`has flat distribution`, () => {
    let COUNT = 50 * 1000
    let LENGTH = 30
    let ALPHABET = 'abcdefghijklmnopqrstuvwxyz'
    let nanoid2 = customAlphabet(ALPHABET, LENGTH)

    let chars = {}
    for (let i = 0; i < COUNT; i++) {
      let id = nanoid2()
      for (let char of id) {
        if (!chars[char]) chars[char] = 0
        chars[char] += 1
      }
    }

    equal(Object.keys(chars).length, ALPHABET.length)

    let max = 0
    let min = Number.MAX_SAFE_INTEGER
    for (let k in chars) {
      let distribution = (chars[k] * ALPHABET.length) / (COUNT * LENGTH)
      if (distribution > max) max = distribution
      if (distribution < min) min = distribution
    }
    ok(max - min <= 0.05)
  })

  test(`changes size`, () => {
    let nanoidA = customAlphabet('a')
    equal(nanoidA(10), 'aaaaaaaaaa')
  })

  test(`is ready for 0 size`, () => {
    equal(customAlphabet('abc')(0), '')
    equal(customAlphabet('abc', 0)(0), '')
    equal(customAlphabet('')(0), '')
    equal(customAlphabet('', 0)(0), '')
  })

  test(`avoids pool pollution, infinite loop`, () => {
    let ALPHABET = 'abcdefghijklmnopqrstuvwxyz'
    let nanoid2 = customAlphabet(ALPHABET)
    nanoid2(2.1)
    let second = nanoid2()
    let third = nanoid2()
    notEqual(second, third)
  })

  test(`supports multi-byte characters`, () => {
    let ALPHABET = 'абвгд'
    let nanoid2 = customAlphabet(ALPHABET, 10)
    for (let i = 0; i < 100; i++) {
      let id = nanoid2()
      equal(id.length, 10)
      for (let char of id) {
        ok(ALPHABET.includes(char))
      }
    }
  })

  test(`supports alphabets bigger than 256 symbols`, () => {
    equal(customAlphabet('a'.repeat(300))(0), '')
  })

  test(`supports non-string alphabets`, () => {
    let ALPHABET = ['a', 'b', 'c', 'd']
    let nanoid2 = customAlphabet(ALPHABET, 10)
    let id = nanoid2()
    equal(id.length, 10)
    for (let char of id) {
      ok(ALPHABET.includes(char))
    }
  })

  if (type === 'node') {
    test(`does not fall in infinite loop`, () => {
      equal(customAlphabet('abc')(0), '')
      equal(customAlphabet('abc', 0)(0), '')
    })
  }
})

